var t=[{title:`Bouw geleidelijk af`,text:`Loop of fiets na een zware loop of rit een paar minuten rustig in plaats van abrupt te stoppen op volle inspanning. Na krachtwerk kan een korte ontspannen wandeling en normale ademhaling prettig voelen. Abrupt stoppen kan je soms licht in het hoofd maken, vooral na lange, intensieve activiteit.`},{title:`Optionele rustige mobiliteit`,text:`Je kunt comfortabele kuit-, heup-, borst- of schouderbewegingen toevoegen als flexibiliteit een van je doelen is of je ze gewoon prettig vindt. Streef naar een milde rekprikkel en forceer geen grote bereiken. Diep rekken direct na een vermoeiende training is optioneel, en pijnlijk rekken werkt tegen je.`},{title:`Wat het bewijs laat zien`,text:`Lichte beweging kan de eerste minuten na een training comfortabeler maken. Er is weinig bewijs dat een standaard cooling-down of rekroutine spierpijn de volgende dag (DOMS) betrouwbaar voorkomt. Geleidelijke opbouw, slaap en herstel blijven belangrijk. Een cooling-down behandelt geen blessure en vervangt geen medische zorg.`},{title:`Stem af op de training`,text:`Een matige wandeling kan eindigen met een of twee rustige minuten. Neem na een zware intervaltraining enkele minuten rustige beweging en ademhaling tot je je stabiel voelt. Gaan duizeligheid, ongewone kortademigheid, pijn op de borst of een flauwtegevoel niet weg, stop dan met trainen en zoek medische hulp.`}];var i=[{label:`NHS: rustige cooling-down`,url:`https://www.nhs.uk/live-well/exercise/strength-and-resistance/body-blast-cool-down/`},{label:`ACE 2026: praktische richtlijnen voor rekken`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`NHS: spierpijn die later opkomt`,url:`https://www.leicspart.nhs.uk/msk-physiotherapy-resources-getting-started/msk-physiotherapy-resources-faqs/`}];var o={sections:t,sources:i};export{o as default,t as sections,i as sources};